using Azure;
using Azure.AI.OpenAI;
using OpenAI;

var openAIClient = new OpenAIClient(
    new Uri("https://my-openai.openai.azure.com/"),
    new AzureKeyCredential("my-api-key")
);

var chatCompletionsOptions = new ChatCompletionsOptions()
{
    DeploymentName = "gpt4o",
    Messages =
    {
        new ChatMessage(ChatRole.System, "You are a helpful assistant that answers questions about Azure."),
        new ChatMessage(ChatRole.User, "What is an App Service plan?")
    },
    Temperature = 0.7f,
    MaxTokens = 500
};

Response<ChatCompletions> response = await openAIClient.GetChatCompletionsAsync(chatCompletionsOptions);
ChatCompletions completions = response.Value;

Console.WriteLine(completions.Choices[0].Message.Content);
Console.WriteLine("Tokens used: " + completions.Usage.TotalTokens);

